#include "WorldAiTerrainBatch.h"
#include "json.hpp"
#include <stdexcept>
namespace Silver::WorldEditor
{
namespace{using Json=nlohmann::json;constexpr std::size_t MaxBytes=1024*1024,MaxStrokes=128;
TerrainBrushMode Mode(std::string_view s){if(s=="raise")return TerrainBrushMode::Raise;if(s=="lower")return TerrainBrushMode::Lower;if(s=="flatten")return TerrainBrushMode::Flatten;if(s=="smooth")return TerrainBrushMode::Smooth;if(s=="noise")return TerrainBrushMode::Noise;if(s=="terrace")return TerrainBrushMode::Terrace;if(s=="erode")return TerrainBrushMode::Erode;if(s=="paintLayer1")return TerrainBrushMode::PaintLayer1;if(s=="paintLayer2")return TerrainBrushMode::PaintLayer2;if(s=="blendMaterial")return TerrainBrushMode::BlendMaterial;if(s=="eraseBlend")return TerrainBrushMode::EraseBlend;if(s=="addFlags")return TerrainBrushMode::AddFlags;if(s=="removeFlags")return TerrainBrushMode::RemoveFlags;throw std::invalid_argument("AI Terrain modo no permitido.");}}
WorldAiTerrainBatch WorldAiTerrainBatch::Decode(std::span<const std::uint8_t>b){if(b.empty()||b.size()>MaxBytes)throw std::invalid_argument("AI TerrainBatch fuera de limites.");Json j;try{j=Json::parse(std::string(reinterpret_cast<const char*>(b.data()),b.size()));}catch(const Json::exception&){throw std::invalid_argument("AI TerrainBatch JSON invalido.");}if(j.value("schema","")!=Schema)throw std::invalid_argument("AI TerrainBatch schema incompatible.");WorldAiTerrainBatch x;x.RequestId=j.value("requestId","");x.MapId=j.value("mapId",-1);x.ExpectedRevision=j.value("expectedRevision",std::uint64_t{});x.Safety=j.value("safety","");if(x.RequestId.empty()||x.MapId<0||x.ExpectedRevision==0||x.Safety!="CANDIDATE_ONLY; NO_AUTO_APPLY"||!j.contains("strokes")||!j.at("strokes").is_array()||j.at("strokes").size()>MaxStrokes)throw std::invalid_argument("AI TerrainBatch inseguro/incompleto.");for(const auto&s:j.at("strokes")){WorldAiTerrainStroke q;q.X=s.value("x",-1);q.Y=s.value("y",-1);q.Brush.Mode=Mode(s.value("mode",""));q.Brush.Radius=s.value("radius",3);q.Brush.Strength=s.value("strength",4);q.Brush.FlattenHeight=s.value("flattenHeight",static_cast<std::uint8_t>(0));q.Brush.Flags=s.value("flags",static_cast<std::uint16_t>(1));q.Brush.Material=s.value("material",0);q.Brush.BlendAlpha=s.value("blendAlpha",128);q.Brush.Falloff=s.value("falloff",0.f);q.Brush.Validate();if(q.X<0||q.Y<0||q.X>=TerrainSide||q.Y>=TerrainSide)throw std::invalid_argument("AI Terrain stroke fuera del mapa.");x.Strokes.push_back(q);}return x;}
bool WorldAiTerrainBatch::Validate(const WorldTerrainDocument&d,int activeMap,std::string&e)const{if(MapId!=activeMap){e="AI TerrainBatch pertenece a otro mapa.";return false;}if(d.Revision()!=ExpectedRevision){e="AI TerrainBatch bloqueado: Terrain revision cambio desde Expected.";return false;}if(d.Active()){e="AI TerrainBatch bloqueado durante stroke activo.";return false;}e.clear();return true;}
bool WorldAiTerrainBatch::Apply(WorldTerrainDocument&d,int activeMap,std::string&e)const{if(!Validate(d,activeMap,e))return false;bool changed=false;for(const auto&s:Strokes){d.Begin(s.Brush);const bool stamped=d.Stamp(s.X,s.Y);if(stamped){d.Commit();changed=true;}else d.Cancel();}if(!changed){e="AI TerrainBatch no produjo cambios.";return false;}e.clear();return true;}
}
